fn main()->Result<(),String>{let compiled=compiled()?;
 with_doc(&compiled,r#"article en "named" body cons section named "named" body nil nil"#,|doc,r,b,a|{
  let section=doc.value.nodes.iter().position(|n|matches!(n.kind,DocKind::Section{..})).ok_or("section")?;
  let title=doc.value.nodes.iter().position(|n|matches!(&n.kind,DocKind::Text{text} if text=="named")&&n.span.as_ref().is_some_and(|s|s.start()<20)).ok_or("title")?;
  let empty=SourceStore::default();let mut codec=FoundationCodec::new(r,&empty,a).map_err(err)?;let wire=nepl3_doc_core::portable::to_value(doc,r,&mut codec,b).map_err(err)?;
  for case in 0..6{
   let mut raw=doc.clone();let mut packet=wire.clone();
   let NdfValue::List(nodes)=&mut fields(&mut fields(&mut packet)[0])[1] else{return Err("nodes".into())};
   let title_origin=fields(&mut nodes[title])[1].clone();let title_span=fields(&mut nodes[title])[2].clone();
   let node=fields(&mut nodes[section]);let NdfValue::List(locations)=&mut node[3] else{return Err("locations".into())};
   match case{
    0=>{raw.value.nodes[section].locations[0].field=DocField::ReferenceTarget;let NdfValue::Variant(tag)=&mut fields(&mut locations[0])[0] else{return Err("field".into())};tag.variant="ReferenceTarget".into();},
    1=>{let duplicate=raw.value.nodes[section].locations[0].clone();raw.value.nodes[section].locations.push(duplicate);locations.push(locations[0].clone());},
    2=>{raw.value.nodes[section].locations[0].span=raw.value.nodes[title].span.clone();fields(&mut locations[0])[2]=title_span;},
    3=>{raw.value.nodes[section].locations[0].origin=raw.value.nodes[title].origin;fields(&mut locations[0])[1]=title_origin;},
    4=>{raw.value.nodes[section].locations[0].origin=Some(OriginId(u64::MAX));let NdfValue::Some(origin)=&mut fields(&mut locations[0])[1] else{return Err("origin".into())};fields(origin)[0]=NdfValue::U64(u64::MAX);},
    _=>{raw.value.nodes[section].locations[0].origin=None;fields(&mut locations[0])[1]=NdfValue::None;},
   }
   let native=raw.validate_structure(r,&mut budget(),&mut SourceAdmission::default());
   let bytes=nepl3_wire::encode(&packet,&mut budget()).map_err(err)?;let mut fresh=SourceAdmission::default();let mut recv=FoundationCodec::new(r,&empty,&mut fresh).map_err(err)?;let received=nepl3_doc_core::portable::from_value(&nepl3_wire::decode(&bytes,&mut budget()).map_err(err)?,r,&mut recv,&mut budget());
   if case==5 {assert!(native.is_ok());let received=received.map_err(err)?;assert_eq!(received.value,raw.value);}else{assert!(native.is_err());assert!(matches!(received,Err(nepl3_doc_core::portable::PortableError::Structure(_))),"case {case}: {received:?}");}
   println!("field native/CBOR case {case}: expected typed relation passes");
  }
  let mut mapped=doc.clone();let own=mapped.value.nodes[section].locations[0].span.clone().ok_or("name span")?;
  let generated=SourceSnapshot::new(SourceId("field-generated".into()),0,"memory:field-generated".into(),b"named".to_vec(),b).map_err(err)?;let generated_span=generated.span(0,5).map_err(err)?;mapped.sources.push(generated);mapped.source_maps.push(Mapping{source:own.clone(),target:generated_span.clone(),kind:MappingKind::Exact});mapped.value.nodes[section].locations[0].span=Some(generated_span.clone());
  mapped.validate_structure(r,b,&mut SourceAdmission::default()).map_err(err)?;roundtrip(&mapped,r,b)?;
  let origin=mapped.value.nodes[section].locations[0].origin.ok_or("field origin")?;let composite=OriginId(mapped.origins.len() as u64);mapped.origins.push(Origin::Composite(vec![mapped.value.nodes[title].origin.ok_or("title origin")?,origin]));mapped.value.nodes[section].locations[0].origin=Some(composite);mapped.validate_structure(r,b,&mut SourceAdmission::default()).map_err(err)?;
  // Field provenance is a contributing cause relation. The same-span literal
  // boundary has a stricter all-token-cause contract; do not mix the two.
  let packet=nepl3_doc_core::portable::to_value(&mapped,r,&mut codec,b).map_err(err)?;
  let mut conflicting=mapped.clone();conflicting.source_maps.push(Mapping{source:doc.value.nodes[title].span.clone().ok_or("title span")?,target:generated_span.clone(),kind:MappingKind::Transformed});assert!(conflicting.validate_structure(r,b,&mut SourceAdmission::default()).is_err());
  let mut missing=packet.clone();fields(&mut missing)[1]=NdfValue::List(vec![]);let mut ambient=SourceStore::default();for source in &mapped.sources{ambient.insert(source.clone()).map_err(err)?;}let mut fresh=SourceAdmission::default();let mut recv=FoundationCodec::new(r,&ambient,&mut fresh).map_err(err)?;assert!(nepl3_doc_core::portable::from_value(&missing,r,&mut recv,&mut budget()).is_err());
