with_doc(&compiled,"article en \"Host\" body cons section same \"H\" body nil cons paragraph cons code Doc article en \"Guest\" body cons section same \"A\" body nil cons section same \"B\" body nil nil cons sentence cons ref same text \"V\" nil nil nil",|doc,r,b,a|{
